-- Public AI summaries validated in the local DeepSeek build: 123 posts, <=100 characters each.
-- Safe to rerun: replace only legacy summaries of the exact same body revision.
ON CONFLICT(post_id) DO UPDATE SET summary=excluded.summary,source=excluded.source,model=excluded.model,summary_version=excluded.summary_version,updated_at=now()
WHERE blog_post_summaries.content_hash=excluded.content_hash
AND (blog_post_summaries.source<>'model' OR blog_post_summaries.summary_version IS DISTINCT FROM excluded.summary_version);
